mapper.select:
SELECT * FROM payment_outbox_event
WHERE status IN ('PENDING', 'RETRYING') AND next_retry_at <= #{now}
ORDER BY id LIMIT #{limit}

mapper.update:
UPDATE payment_outbox_event
SET status = 'RETRYING', locked_by = NULL, locked_at = NULL, lock_until = NULL, claim_token = NULL
WHERE status = 'PROCESSING' AND lock_until < #{now}

UPDATE payment_outbox_event
SET status = 'PROCESSING', locked_by = #{workerId}, claim_token = #{claimToken},
  locked_at = #{now}, lock_until = #{lockUntil}
WHERE event_id = #{eventId} AND status IN ('PENDING', 'RETRYING') AND next_retry_at <= #{now}

UPDATE payment_outbox_event SET status = 'PUBLISHED', published_at = #{publishedAt},
  locked_by = NULL, locked_at = NULL, lock_until = NULL, claim_token = NULL
WHERE event_id = #{eventId} AND status = 'PROCESSING' AND claim_token = #{claimToken}
  AND lock_until >= #{now}
